import math

def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length == 0:
        return float('inf')  # cannot move if length is zero and d != 0
    if length == d:
        return 1
    if length > d:
        # Cannot reach exactly (d,0) in one jump if length > d,
        # because the jump length is fixed and target is closer than jump length.
        # But since moves can be in any 2D direction, we cannot scale the jump.
        # So one jump will overshoot and can't land exactly at (d,0).
        # So minimum jumps is 2 in this case (e.g. jump somewhere else, then adjust).
        return 2
    if length < d:
        # If two jumps can reach exactly (d,0),
        # that means the target is reachable as the sum of two vectors of length 'length'.
        # Geometrically, two jumps of fixed length can reach any point at distance <= 2*length.
        # Since d <= 2*length and d > length, 2 jumps suffice.
        if 2 * length >= d:
            return 2
        # Otherwise, more jumps needed
        return math.ceil(d / length)
    # fallback (should not reach here)
    return math.ceil(d / length)

