def prime_length(string):
    n = len(string)
    if n < 2:
        return 0
    if n in (2, 3):
        return 1
    if n % 2 == 0 or n % 3 == 0:
        return 0
    # Check divisibility by 6k ± 1 up to sqrt(n)
    # Without loops or recursion, we unroll checks for all k where (6k ± 1)^2 <= n
    # For typical string lengths, checking up to 31 suffices (31^2=961)
    checks = [
        5, 7,
        11, 13,
        17, 19,
        23, 25,
        29, 31,
    ]
    for c in checks:
        if c * c > n:
            break
        if n % c == 0:
            return 0
    return 1

